import * as wt from 'node:worker_threads';

async function main(): Promise<void> {
  const err = (f: () => void): string => { try { f(); return 'ok'; } catch (e: any) { return `${e.name} ${e.code} ${e.message}`; } };
  const worker = new wt.Worker('setInterval(() => {}, 1000)', { eval: true });
  const channel = new wt.MessageChannel();
  const port1 = channel.port1;
  const port2 = channel.port2;
  console.log('dup', err((): void => { worker.postMessage({}, [port2, port2]); }));
  console.log('unlisted', err((): void => { worker.postMessage({ p: port2 }); }));
  const c = new wt.MessageChannel();
  console.log('transfer', err((): void => { worker.postMessage({}, [c.port1]); }));
  console.log('again', err((): void => { worker.postMessage({}, [c.port1]); }));
  c.port2.close();
  console.log('closed', err((): void => { worker.postMessage({}, [c.port2]); }));
  console.log('own', err((): void => { port1.postMessage('x', [port1]); }));
  await worker.terminate();
  console.log('terminated');
}
